    // Back-Face Culling e Ordenação (Profundidade Sorting)
    List<Triangle> visibleTriangles = [];

    for (int i = 0; i < staticIndices.length; i++) {
      final int idx0 = staticIndices[i][0];
      final int idx1 = staticIndices[i][1];
      final int idx2 = staticIndices[i][2];

      // Pega os vértices transformados (precisa verificar se foram processados no loop acima)
      // Nota: Em uma implementação robusta, armazenaria os dados transformados em uma lista paralela
      // para acesso rápido sem re-calcular. Aqui assumimos que o loop acima popou a lista ou verificamos índice.
      // Vamos refazer a verificação rápida aqui para simplicidade:

      Vector4 v0 = transform.transformed(Vector4(staticVertices[idx0].x, staticVertices[idx0].y, staticVertices[idx0].z, 1.0));
      Vector4 v1 = transform.transformed(Vector4(staticVertices[idx1].x, staticVertices[idx1].y, staticVertices[idx1].z, 1.0));
      Vector4 v2 = transform.transformed(Vector4(staticVertices[idx2].x, staticVertices[idx2].y, staticVertices[idx2].z, 1.0));

      if (v0.w == 0 || v1.w == 0 || v2.w == 0) continue;

      // Normalização dos vetores
      Vector3 edge1 = Vector3(v1.x / v1.w - v0.x / v0.w, v1.y / v1.w - v0.y / v0.w, v1.z / v1.w - v0.z / v0.w);
      Vector3 edge2 = Vector3(v2.x / v2.w - v0.x / v0.w, v2.y / v2.w - v0.y / v0.w, v2.z / v2.w - v0.z / v0.w);

      Vector3 normal = edge1.cross(edge2).normalized();
      Vector3 viewVector = Vector3(0, 0, 1); // Direção da câmera (assumindo que a câmera olha para +Z relativo à view matrix)

      // Produto escalar
      double dotProduct = normal.dot(viewVector);

      // Se positivo, é face frontal (considerando a direção da câmera)
      if (dotProduct > 0) {
        double depth = (v0.x / v0.w + v1.x / v1.w + v2.x / v2.w) / 3.0;
        visibleTriangles.add(Triangle([idx0, idx1, idx2], depth));
      }
    }

    // Ordenação por profundidade (mais distante primeiro)
    visibleTriangles.sort((a, b) => b.depth.compareTo(a.depth));

    // Preparação de buffers finais (removendo vértices duplicados)
    List<int> renderedIndices = [];
    List<double> renderedPositions = [];
    List<double> renderedTexcoordsList = [];

    Map<int, int> vertexMap = {};
    int currentIndex = 0;

    for (var tri in visibleTriangles) {
      for (int idx in tri.indices) {
        // Busca o vértice transformado correspondente
        Vector4 v = transform.transformed(Vector4(staticVertices[idx].x, staticVertices[idx].y, staticVertices[idx].z, 1.0));

        if (v.w == 0) continue;

        if (!vertexMap.containsKey(idx)) {
          vertexMap[idx] = currentIndex++;
          renderedPositions.add(v.x / v.w + width / 2.0);
          renderedPositions.add(v.y / v.w + height / 2.0);
          // Obter texcoord novamente ou guardar na primeira vez
          // Para performance, seria melhor guardar as texcoords numa lista separada durante o loop de vertices
          // Mas para este exemplo, recalculamos ou assumimos que o índice original mantém a UV
          // Na prática, mapeie o índice original para a UV correta.
          // Simplificando: assumimos que a UV não muda com rotação/translação (ortográfica na UV)
          // Se houver rotação complexa na UV, isso precisa de interpolação matricial.
          // Aqui usaremos a UV original do staticTexcoords[idx] assumindo que a rotação 3D não gira a textura.
          renderedTexcoordsList.add(staticTexcoords[idx].dx * texture.width);
          renderedTexcoordsList.add(staticTexcoords[idx].dy * texture.height);
        }
        renderedIndices.add(vertexMap[idx]!);
      }
    }

    if (renderedIndices.isEmpty) return;

    final Uint16List indexBuffer = Uint16List.fromList(renderedIndices);
    final Float32List positionsBuffer = Float32List.fromList(renderedPositions);
    final Float32List texcoordsBuffer = Float32List.fromList(renderedTexcoordsList);

    final verticesData = Vertices.raw(
      VertexMode.triangles,
      positionsBuffer,
      textureCoordinates: texcoordsBuffer,
      indices: indexBuffer,
    );

    final paint = Paint()
      ..shader = ImageShader(
        texture,
        TileMode.clamp,
        TileMode.clamp,
        Matrix4.identity().storage, // A shader gerencia a projeção se necessário, ou use a matriz MVP aqui
      );

    // Importante: Se a ImageShader não aplicar a transformação de câmera automaticamente,
    // você precisa passar a matriz MVP nesta linha.
    // No entanto, CustomPainter desenha no espaço 2D do Canvas. 
    // A projeção 3D->2D deve ser feita ANTES de criar o buffer de vértices (como fizemos no loop).
    // Portanto, a matriz aqui pode ser identidade se a projeção já foi aplicada nas coordenadas X/Y.
    // Se quiser usar a imagem shader para projeção, a matemática acima no loop de vertices precisaria mudar.
    // Mantendo a abordagem clássica: Projeção manual nos floats.

    canvas.drawVertices(verticesData, BlendMode.dstOver, paint);
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) {
    return true;
  }
}
